/// Safe version for non-critical paths
#[inline]
pub fn try_get_quantum_crypto() -> Option<&'static Arc<crate::quantum_crypto::QNetQuantumCrypto>> {
    GLOBAL_QUANTUM_CRYPTO.get()
}

